package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchRequest struct {
	TenantID string `json:"tenant_id"`
	Filters  map[string]string `json:"filters"`
	Fields   []string `json:"fields"`
}

func buildSelectClause(fields []string) string {
	if len(fields) == 0 {
		return "id, name, email, department"
	}
	allowed := map[string]bool{"id": true, "name": true, "email": true, "department": true, "created_at": true, "role": true}
	var safe []string
	for _, f := range fields {
		if allowed[strings.ToLower(strings.TrimSpace(f))] {
			safe = append(safe, strings.ToLower(strings.TrimSpace(f)))
		}
	}
	if len(safe) == 0 {
		return "id, name, email, department"
	}
	return strings.Join(safe, ", ")
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Tenant isolation - parameterized
	baseQuery := fmt.Sprintf("SELECT %s FROM employees WHERE tenant_id = $1", buildSelectClause(req.Fields))
	args := []interface{}{req.TenantID}
	argIdx := 2

	// Dynamic filter construction
	for column, value := range req.Filters {
		// Column name validation - only allow known columns
		allowedCols := map[string]bool{"department": true, "role": true, "name": true, "email": true}
		if !allowedCols[strings.ToLower(column)] {
			continue
		}
		// Value is parameterized for simple equality
		if strings.Contains(value, "*") {
			// Wildcard search - convert * to % for LIKE
			likeVal := strings.ReplaceAll(value, "*", "%")
			baseQuery += fmt.Sprintf(" AND %s LIKE '%s'", strings.ToLower(column), likeVal)
		} else {
			baseQuery += fmt.Sprintf(" AND %s = $%d", strings.ToLower(column), argIdx)
			args = append(args, value)
			argIdx++
		}
	}

	baseQuery += " LIMIT 100"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []map[string]interface{}
	cols, _ := rows.Columns()
	for rows.Next() {
		values := make([]interface{}, len(cols))
		ptrs := make([]interface{}, len(cols))
		for i := range values {
			ptrs[i] = &values[i]
		}
		rows.Scan(ptrs...)
		row := make(map[string]interface{})
		for i, col := range cols {
			row[col] = values[i]
		}
		results = append(results, row)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/v2/employees/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
